window.RP_SESSION={"id":"S-01a17ea5bb32","messages":[{"id":"RP-0270470","time":"2026-09-12T00:50:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"길드 물가에는 언제나 하얀머리의 소년이 앉아있습니다.","characters":["P-a161473e74e0"]},{"id":"RP-0270471","time":"2026-09-12T00:50:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"새하얗고 나풀거리는 옷을입은, 하프엘프 소년이","characters":["P-a161473e74e0"]},{"id":"RP-0270472","time":"2026-09-12T00:51:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"개울가에서 헤엄치는 송사리들을 구경하며 여가시간을 즐기고있네요~","characters":["P-a161473e74e0"]},{"id":"RP-0270473","time":"2026-09-12T00:54:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 리엔씨, 아니세요? \"\n\n항상, 개울가에서 발을 담구며 노는 길드의 잉여엘프가, 리엔을 발견하고, 인사합니다.","characters":["P-2bd2e06457e6"]},{"id":"RP-0270474","time":"2026-09-12T00:57:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"스노우씨~!\"\n\n리엔은 스노우를 발견하고 반갑게 손을흔들어 인사합니다~\n\n\"어서와요! 오랜만에 시간이남아서 개울가에 나와있었어요\"","characters":["P-a161473e74e0"]},{"id":"RP-0270475","time":"2026-09-12T01:00:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 요즘, 바쁜일이라도 있으셨나요? 아, 임무를 다녀오셨을려나요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270476","time":"2026-09-12T01:01:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"의뢰다녀왔더니 길드가많이 변해있더라구요\"","characters":["P-a161473e74e0"]},{"id":"RP-0270477","time":"2026-09-12T01:01:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"커플도늘고\"","characters":["P-a161473e74e0"]},{"id":"RP-0270478","time":"2026-09-12T01:02:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 사랑, 좋지않나요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270479","time":"2026-09-12T01:03:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"저는아직 제대로 사랑해본적이 없어서 모르겠어요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270480","time":"2026-09-12T01:03:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"하지만 경험해본다면, 분명 좋은거라고 말할거같아요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270481","time":"2026-09-12T01:03:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"사랑하는 사람들은 항상 웃고있었거든요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270482","time":"2026-09-12T01:04:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 음, 사실 저도 해본적은 없어요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270483","time":"2026-09-12T01:04:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"그렇게 긴세월동안요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0270484","time":"2026-09-12T01:05:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 하지만, 그런만큼, 원하고있어요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270485","time":"2026-09-12T01:05:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"사랑을 하게되면 분명히 재밌을거에요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270486","time":"2026-09-12T01:06:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 네, 저도 분명. 그렇게생각하고있어요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270487","time":"2026-09-12T01:06:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 분명, 아주, 아름다운...일일거에요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270488","time":"2026-09-12T01:06:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"보통은 부모님의 사랑에서 사랑을 배워야한다는데, 우리 엄마는 저를낳다가 돌아가셔서 그런건 못배웠어요. 그냥 추측하는거에요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270489","time":"2026-09-12T01:06:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"아빠는 항상 울상이셨는데 사랑에빠진 사람들은 언제나 웃고있잖아요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270490","time":"2026-09-12T01:07:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...아버지께서, 어머니를 사랑하셨기에, 그만큼 큰 빈자리를, 느끼셨던게아닐까요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270491","time":"2026-09-12T01:07:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"정말그게 사랑 때문만일지는... 모르겠지만요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270492","time":"2026-09-12T01:07:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ...그러게요. 다른이유도, 분명히 있을 수도 있을테지만요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270493","time":"2026-09-12T01:07:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"네레이드!\"\n\n리엔이 정령을 부릅니다.\n\n\"스노우씨, 그러고보니 네레이드가 묘기를 익혔어요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270494","time":"2026-09-12T01:07:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-a161473e74e0"]},{"id":"RP-0270496","time":"2026-09-12T01:08:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"반짝반짝~","characters":["P-a161473e74e0"]},{"id":"RP-0270497","time":"2026-09-12T01:09:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"네레이드가 달빛을받아 마치 푸르스름한 미러볼처럼 빛납니다~!","characters":["P-a161473e74e0"]},{"id":"RP-0270498","time":"2026-09-12T01:09:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"짜잔~ 이쁘죠?\"","characters":["P-a161473e74e0"]},{"id":"RP-0270499","time":"2026-09-12T01:09:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 정말, 아름다운걸요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270500","time":"2026-09-12T01:10:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"스노는, 자신도 무언가를 보여주기위해서. 마법을 사용합니다.","characters":["P-2bd2e06457e6"]},{"id":"RP-0270501","time":"2026-09-12T01:10:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"마치, 그들의 주변에만 눈이 내리듯, 눈결정이 생기며...빛이납니다.","characters":["P-2bd2e06457e6"]},{"id":"RP-0270502","time":"2026-09-12T01:10:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"우와~\"","characters":["P-a161473e74e0"]},{"id":"RP-0270503","time":"2026-09-12T01:10:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 어때요? 아름답지않아요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270504","time":"2026-09-12T01:10:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"짱이뻐요! 마법은정말 아름답네요~\"","characters":["P-a161473e74e0"]},{"id":"RP-0270505","time":"2026-09-12T01:11:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 후후ㅡ, 감사해요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270506","time":"2026-09-12T01:11:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 이것 참, 보람이있네요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270507","time":"2026-09-12T01:12:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"스노우의 의상을보고\n\n\"스노우씨도 남쪽에서 오셨나요? 여기사람들은 남쪽에서 입던옷을 입으면 조금은 이상하게 보더라구요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270508","time":"2026-09-12T01:12:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"노출이 과하다느니, 무희같다느니.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270509","time":"2026-09-12T01:12:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"우리 고향마을에서는 이렇게 안입으면 여름에는 쓰러졌는데 말이에요!\"","characters":["P-a161473e74e0"]},{"id":"RP-0270510","time":"2026-09-12T01:12:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 아뇨. 저는 북쪽에서 내려왔답니다. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270511","time":"2026-09-12T01:13:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"반대쪽이네요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270512","time":"2026-09-12T01:13:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 북부의 산에서 100년간 홀로살다, 내려왔어요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270513","time":"2026-09-12T01:13:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"복식이뭔가 제가 태어났던 고향마을의 복식같아서 반가웠는데, 그건 아쉽네요. 그래도 북부얘기도 들어보고 싶어요~!\"","characters":["P-a161473e74e0"]},{"id":"RP-0270514","time":"2026-09-12T01:14:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 전, 다른분들과 달리 저혼자 산 기간이 꽤나 길어서요... \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270515","time":"2026-09-12T01:14:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 제 생활이라면 말씀드릴 수 있지만, 그게 일반적인 북부의 생활은아닐것 같아요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270516","time":"2026-09-12T01:14:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"그러면 이야기의 대부분은 차갑고 거친 바위산맥이겠네요~\"","characters":["P-a161473e74e0"]},{"id":"RP-0270517","time":"2026-09-12T01:14:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 맞아요. 그렇죠. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270518","time":"2026-09-12T01:14:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 하지만...정말 눈은, 아름다웠어요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270519","time":"2026-09-12T01:15:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"그래서 눈에서 마법형태를 따오신건가요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0270520","time":"2026-09-12T01:15:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 네. 맞아요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270521","time":"2026-09-12T01:15:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"멜라니온 어르신은 시냇물들이나 나뭇잎에서 마법형태를 따오시고, 스노우씨는 눈에서... 엘프들의 마법은 그렇게 작동하는게 보통인가요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0270522","time":"2026-09-12T01:16:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 음, 제 생각을 말씀드리자면... \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270523","time":"2026-09-12T01:17:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 마법은 현상이에요. 그리고, 저희가 하는건 그현상을 재현해내기 위하여 영창을 하는것이죠. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270524","time":"2026-09-12T01:18:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그 현상이라는것의 심상을 어떻게 떠올리느냐에 따라, 마법사들끼리도 어떤식인지. 다른편이라고. 저는생각해요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270525","time":"2026-09-12T01:18:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n지능판정 실패","characters":["P-a161473e74e0"]},{"id":"RP-0270526","time":"2026-09-12T01:18:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"대충 멋진거네요~\"\n\n얼버무리기","characters":["P-a161473e74e0"]},{"id":"RP-0270527","time":"2026-09-12T01:19:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그럼요, 마법은 이리도, 아름다울 수 있으니까요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270528","time":"2026-09-12T01:19:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"마법은 정령들이랑 비슷하면서도 다른거같아요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270529","time":"2026-09-12T01:20:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 정령,생각해보니 저는 정령에 대해서도 궁금헀었어요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270530","time":"2026-09-12T01:20:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 정령들은, 어떤...느낌일까요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270531","time":"2026-09-12T01:20:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"저는 태어날때부터 정령이랑 소통해왔어서 정령들이랑 얘기가 안통하는게 더 어떤느낌일지 궁금해요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270532","time":"2026-09-12T01:21:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그것도, 그럴수 있을거같네요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270533","time":"2026-09-12T01:21:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"숲속의 정령들이 마치 바위나 모래더미처럼 침묵하는 세상은 얼마나 고요할까요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0270534","time":"2026-09-12T01:22:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"신비라는건 그런거같아요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270535","time":"2026-09-12T01:22:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"직접 겪어보는사람이 아니면 아무리 잘설명해도 이해하기 힘든것.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270536","time":"2026-09-12T01:22:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"그러니까 신비가 아닐까요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0270537","time":"2026-09-12T01:22:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 분명히ㅡ, 그럴거라 생각해요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270538","time":"2026-09-12T01:23:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그래서, 세상에 신비라고 불리는것이겠지요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270539","time":"2026-09-12T01:24:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"우리는 신비로운 세계에 살고있어서 다행이에요. 모든게 밝혀져버린 세계에 살고있다면 얼마나 지루하겠어요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0270540","time":"2026-09-12T01:24:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 음, 그건 그렇지 않을것이에요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270541","time":"2026-09-12T01:25:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"상상해봐요, 아름다운 것들을 모조리 조각조각 해부해놓고 관찰해서 그 기록들을 누구나 볼수있는 커다란 도서관안에 전시해놓는 세계에 더이상 무슨 흥미가 남아있겠어요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0270542","time":"2026-09-12T01:25:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 저희 길드원분들만봐도, 그렇지않은분들도 모두, 즐겁게살아가고 계시잖아요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270543","time":"2026-09-12T01:25:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"어쨌든간에요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270544","time":"2026-09-12T01:25:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"네레이드를 쓰다듬습니다.","characters":["P-a161473e74e0"]},{"id":"RP-0270545","time":"2026-09-12T01:27:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"스노는 발에 물을 담군채 앉아. 하늘을 올려다봅니다.","characters":["P-2bd2e06457e6"]},{"id":"RP-0270546","time":"2026-09-12T01:30:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"달이 예쁘네요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270547","time":"2026-09-12T01:30:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그러게요. 정말...아름다운 풍경이에요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270548","time":"2026-09-12T01:30:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 달도, 별도. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270549","time":"2026-09-12T01:31:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"오늘 오후즈음에 해가 지기전에도 달을 봤었어요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270550","time":"2026-09-12T01:31:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"낮에도 가끔씩 달이있는거, 스노우씨라면 오래도록 살아오셨으니까 보셨겠지만 저는 오늘처음 알았거든요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270551","time":"2026-09-12T01:32:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"어릴때는 어려서 몰랐고, 얼마전까지는 길거리에서 거지생활, 도적생활이나 전전하면서 하늘을 올려다볼 여유가 없었거든요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270552","time":"2026-09-12T01:32:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"이렇게...\"","characters":["P-a161473e74e0"]},{"id":"RP-0270553","time":"2026-09-12T01:32:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"동료와함께 하늘을 올려다보고 있으니까 좋네요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270554","time":"2026-09-12T01:34:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그러게요. 아름다운걸 함께본다는건, 좋은일이네요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270555","time":"2026-09-12T01:34:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 저는 되려...하늘을 올려다본일이, 굉장히 많았던거같아요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270556","time":"2026-09-12T01:36:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"하늘을 같이 올려다봐야 하는데.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270557","time":"2026-09-12T01:36:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"제게는 하늘이, 스노우씨에겐 같이가 없었나보네요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270558","time":"2026-09-12T01:37:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 후후. 그러게요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270559","time":"2026-09-12T01:37:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 혼자만있으려니. 쓸쓸했던거같아요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270560","time":"2026-09-12T01:37:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그때 당시에는, 크게 느끼지 못했었지만요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270561","time":"2026-09-12T01:41:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"이제부터라도 하늘이 있고, 같이가 있으니까 다행이네요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270562","time":"2026-09-12T01:41:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 정말, 길드에 들어오길 선택한게. 좋다는 생각이들어요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270563","time":"2026-09-12T01:42:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 리엔씨는, 길드에 들어와서, 이루고 싶던것이 있나요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270564","time":"2026-09-12T01:42:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"구더기없는 고기랑 썩지않은 빵을 특식이아니라 매일매일 먹는거요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270565","time":"2026-09-12T01:43:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"잘훔치면 원래도 먹을수 있었지만, 어린애 몸으로는 훔치다가 걸려서 얻어맞는게 더 잦았거든요~\"","characters":["P-a161473e74e0"]},{"id":"RP-0270566","time":"2026-09-12T01:44:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n스노는 질문을 잘못했나. 생각해보았다가, 이내, 마음을 다잡고는.\n\n\" 그 꿈, 이뤘나요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270567","time":"2026-09-12T01:45:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"네, 길드에서는 다행히 썩은고기를 주지는 않더라구요~\"","characters":["P-a161473e74e0"]},{"id":"RP-0270568","time":"2026-09-12T01:45:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"그리고...\"","characters":["P-a161473e74e0"]},{"id":"RP-0270569","time":"2026-09-12T01:46:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"조금 부끄러운 얘기지만, 동화책속에 나오는 영웅이되고 싶었어요~!\"","characters":["P-a161473e74e0"]},{"id":"RP-0270570","time":"2026-09-12T01:46:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"오래오래 행복하게 살았답니다~!로 끝나는 그런 동화책!\"","characters":["P-a161473e74e0"]},{"id":"RP-0270571","time":"2026-09-12T01:47:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"아빠가 돌아가시기 전까지 읽어주시던 그런 동화책말예요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270572","time":"2026-09-12T01:48:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 부끄러울 이유가있나요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270573","time":"2026-09-12T01:48:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 저도, 동경하거든요. 동화속의 이야기. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270574","time":"2026-09-12T01:49:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 저는, 길드에, 인생의 반려자를 찾기위해 왔었어요. 길드에서 세상을 돌아다니다보면, 만날 수 있을거라 생각해서요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270575","time":"2026-09-12T01:49:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 왕자님, 이라고 해야할까요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270576","time":"2026-09-12T01:49:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"그렇죠!\"\n\n아까전의 네레이드만큼이나 눈동자를 반짝거리고는.\n\n\"동화란정말 멋진거같아요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270577","time":"2026-09-12T01:50:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"저는어쩌면 공주님보다는 사악한 용을 찾아온거같아요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270578","time":"2026-09-12T01:50:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"영웅이 되려면 물리쳐야하는 용말이죠.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270579","time":"2026-09-12T01:51:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 그런것도, 분명, 멋진꿈이에요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270580","time":"2026-09-12T01:51:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"시간이 늦었는데 스노우씨는 주무시러가지 않나요? 동화를 읽어주면서 잠들시간은 지난거같아요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270581","time":"2026-09-12T01:52:00+09:00","room":"RP","name":"스노우 글로우","profile":"GM","identity":"reviewed","type":"dialogue","body":"\" 슬슬, 자러 드갈생각도 있었는데, 리엔씨는 어떡하실 생각이신가요? \"","characters":["P-2bd2e06457e6"]},{"id":"RP-0270582","time":"2026-09-12T01:59:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"저도이제 자러가야죠.\"","characters":["P-a161473e74e0"]},{"id":"RP-0270583","time":"2026-09-12T02:14:00+09:00","room":"RP","name":"리엔 에이라스","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-a161473e74e0"]}]};
